from engine import *
topics=[
I('web','От страница към страница в световната мрежа',P('Когато отвориш сайт на училище и натиснеш „Новини“, преминаваш към друга информация чрез връзка. Тази система от свързани страници е <strong>World Wide Web — WWW</strong>, световната уеб мрежа. Интернет е по-широката инфраструктура, чрез която използваме и други услуги.','<strong>Хипертекст</strong> е текст, който съдържа връзки към друга информация. Връзката може да води до друга страница, файл или място в същата страница. Тя може да е поставена и върху изображение.','Страниците се разглеждат с <strong>браузър</strong>, например Edge, Chrome, Firefox или Safari. Браузърът прочита описанието на страницата и показва текста, изображенията и останалите елементи.')+E('Пример: в страницата „Нашето училище“ натискаш „Галерия“. Отваря се колекция от снимки. Текстът „Галерия“ е бил хипервръзка, а браузърът е показал нейния адресат.'),[('Начална страница','Виждаме „Нашето училище“'),('Връзка Галерия','Натискаме текста'),('Браузър','Показва свързаната страница със снимки')],C('Кои твърдения са верни?',['Браузърът показва уеб страници.','Хипервръзката може да води към друга страница.','Връзка може да има и върху изображение.','WWW означава всички възможни услуги в интернет без разлика.','Връзка може да води към част от същата страница.','Надписът Галерия задължително е снимков файл, а не връзка.'],[0,1,2,4],'Браузърът показва свързани документи. WWW е уеб услугата, а връзките могат да са текстови или графични и да имат различни цели.')),
I('html','HTML: описание, което браузърът разбира',P('<strong>HTML</strong> е език за описание и подреждане на съдържанието на уеб страница. Името идва от HyperText Markup Language. Не е нужно да помниш дългото английско име, за да разбереш идеята: отбелязваме кое е абзац, заглавие, изображение или връзка.','Отбелязванията се наричат <strong>тагове</strong> и се записват в ъглови скоби. Например <code>&lt;p&gt;</code> започва абзац, а <code>&lt;/p&gt;</code> го завършва. Самите скоби и тагове обикновено не се виждат като текст в готовата страница.','HTML документът е текстов файл, често с разширение <strong>.html</strong> или <strong>.htm</strong>. Той може да посочва и други ресурси: изображения, звук или видео. Браузърът ги използва, за да покаже страницата.')+'<pre>&lt;p&gt;Здравейте, &lt;strong&gt;приятели&lt;/strong&gt;!&lt;/p&gt;</pre>'+E('Резултатът е абзац „Здравейте, приятели!“, в който думата <strong>приятели</strong> е подчертана чрез по-плътно изписване. Браузърът използва описанието, вместо да показва всички тагове.'),[('HTML файл','Описание на съдържанието'),('<p> / <strong>','Абзац / важен текст'),('На екрана','Здравейте, приятели!')],C('Кои твърдения за HTML са верни?',['Описва елементи на уеб страница.','Таговете се записват в ъглови скоби.','Файлът може да има разширение .html.','Браузърът винаги показва всички тагове като обикновен текст в страницата.','HTML може да посочва адрес на изображение.','HTML файлът непременно е единствено фотография.'],[0,1,2,4],'HTML описва съдържание и връзки към ресурси. Браузърът тълкува това описание, за да покаже страницата.')),
I('site','Страница и сайт: една част и цялото',P('<strong>Уеб страница</strong> е отделен документ с неговите ресурси, който браузърът показва. <strong>Уеб сайт</strong> е организирана съвкупност от тематично свързани страници под общ адрес. Една страница е част от сайта, както един раздел е част от книга.','В училищния пример сайтът има Начало, Новини, Галерия и Контакти. Менюто съдържа връзки към тези страници. Наличието на общо име и подредена навигация помага на посетителя да разбере къде се намира.','Първият уеб сайт е свързан с работата на Тим Бърнърс-Лий в CERN, Швейцария. Началните сървър и страници са от 1990 г.; на <strong>6 август 1991 г.</strong> проектът е представен по-широко извън CERN. Така разграничаваме създаването от публичното разпространяване.')+E('Ако от Галерия отвориш Контакти, си сменил страницата, но може да останеш в същия училищен сайт. Ако натиснеш външна връзка, можеш да напуснеш този сайт.'),[('Училищен сайт','Начало + Новини + Галерия + Контакти'),('Страница Галерия','Една част от сайта'),('CERN / Тим Бърнърс-Лий','Началото на Web; публично представяне през 1991 г.')],C('Кои твърдения са верни?',['Сайтът може да съдържа няколко свързани страници.','Галерия и Контакти могат да са в един сайт.','Смяната на страница винаги означава смяна на сайта.','Навигацията помага да намерим страниците.','Тим Бърнърс-Лий и CERN са свързани с началото на Web.','Една страница и цял многолистов сайт винаги са напълно едно и също понятие.'],[0,1,3,4],'Страницата е част, сайтът е организираното цяло. Връзките може да са вътрешни или външни; навигацията свързва частите.')),
I('purposes','Каква работа върши сайтът?',P('За да определим вида на сайт, първо гледаме <strong>за какво служи</strong>. Едно и също оформление може да се използва с различна цел, затова само цветът на фона не е достатъчен за класификация.','<strong>Личен сайт</strong> представя човек или малка група. <strong>Блогът</strong> публикува последователни записи, често с възможност за коментари; не е задължително да има форум. <strong>Корпоративен сайт</strong> представя организация. <strong>Електронен магазин</strong> предлага стоки за покупка, а <strong>новинарски сайт</strong> публикува новини и репортажи.','В готовия училищен пример има сведения за училището, новини и контакти. Той има представителна и информационна цел. Един сайт може да съчетава функции, например представяне на клуб и раздел с неговите новини.')+T(['Нужда','Подходящ пример'],[['Представяне на фотограф','Личен сайт.'],['Покупка на спортни обувки','Електронен магазин.'],['Информация за училище','Сайт на организация.']]),[('Цел','Какво трябва да намери или направи посетителят?'),('Магазин','Разглеждане и покупка на стоки'),('Блог','Последователни публикации')],C('Кои съчетания са правилни?',['Електронен магазин — продажба на стоки.','Новинарски сайт — новини и репортажи.','Личен сайт — представяне на човек.','Видът на сайта се определя единствено от цвета на фона.','Корпоративен сайт — информация за организация.','Блогът задължително трябва да съдържа отделен дискусионен форум.'],[0,1,2,4],'Класифицираме по предназначение. Сайтът може да съчетава роли; блог не означава непременно отделен форум.')),
I('static','Статичен сайт: подготвената страница се изпраща',P('Представи си папка с готови страници: index.html, gallery.html и contacts.html. Когато посетителят поиска Контакти, компютърът, който обслужва сайта, изпраща готовия файл. Този компютър наричаме <strong>сървър</strong>.','Това е основната идея на <strong>статичния сайт</strong>: съдържанието на страниците е подготвено предварително. Ако телефонният номер в contacts.html трябва да се промени, обновяваме съответния източник и публикуваните файлове.','Статичният сайт е удобен за малко представяне, чието съдържание не се променя непрекъснато. Това не означава, че всяка статична страница е без изображения, движение или бутони. Думата описва начина на подготвяне и изпращане, а не обещава конкретен външен вид или скорост.')+E('Пример: туристически клуб има три готови страници с маршрути. Посетителите получават подготвеното съдържание; при нов маршрут авторът обновява сайта.'),[('Файлове','index.html, gallery.html, contacts.html'),('Посетител иска Контакти','Сървърът изпраща готовата страница'),('Обновяване','Промяна и публикуване на новия файл')],C('Кои твърдения описват показания статичен сайт?',['Страниците са подготвени предварително.','Сървърът може да изпрати готов HTML файл.','Не може да има никакви изображения.','При промяна се обновяват съответните файлове.','Подходящ е например за малък рядко променян сайт.','Статичен означава гарантирано по-бърз от всеки друг сайт при всякакви условия.'],[0,1,3,4],'Статичността описва подготовката на съдържанието. Външният вид и реалната скорост зависят и от изображения, код, сървър и връзка.')),
I('dynamic','Динамичен сайт: страницата се сглобява при заявка',P('В магазин искаш да видиш само обувките с номер 38. Сайтът може да използва заявката ти, наличните данни и готово оформление, за да състави подходящия списък. Това е пример за <strong>динамично създаване на страница</strong>.','В описания в учебника модел сървърът използва програмен код, данни и шаблон. <strong>База данни</strong> е организирано място за записи — например продукти, цени и наличности. <strong>Шаблонът</strong> определя общото подреждане.','<strong>CMS</strong> е система за управление на съдържание. Чрез нея редактор може да добави новина или да поправи текст, без за всяка промяна да пише целия HTML на ръка. Статични и динамични подходи могат да се съчетават; по самия външен вид не винаги можем да докажем кой е използван.')+E('В готовия пример са избрани размер 38 и категория „Маратонки“. Показват се два съответстващи продукта. Друг избор може да даде друг списък.'),[('Избор на посетителя','Маратонки, номер 38'),('Данни + код + шаблон','Съставят подходящ списък'),('CMS','Редактиране на съдържание през интерфейс')],C('Кои твърдения са верни?',['Динамичният модел може да съставя страница според заявката.','Базата данни може да съдържа продукти и цени.','CMS улеснява редактирането на съдържание.','Всеки сайт с красива снимка задължително е динамичен.','Шаблонът задава общо оформление.','Външният вид винаги доказва как е изграден сайтът.'],[0,1,2,4],'Моделът свързва заявка, данни и оформление. CMS е средство за управление; самата картина на екрана не доказва вътрешната технология.')),
I('editors','С какви инструменти се създават страниците?',P('<strong>Текстов редактор</strong> позволява да напишем HTML кода. Например във Visual Studio Code или Notepad++ можем да въведем таговете и да запазим .html файл. Браузърът показва резултата, а редакторът е мястото за промяна на описанието.','<strong>Визуалният редактор</strong> предлага бутони и работно поле: добавяме текст, изображение или връзка, като виждаме оформлението. Настолният редактор е програма на компютъра. В учебника са посочени SeaMonkey Composer, Google Web Designer, Expression Web, BlueGriffon и WebSite X5; част от тези примери са по-стари или са предназначени за определени задачи.','<strong>Онлайн редакторът</strong> се използва през браузър. Примери са Wix и Google Sites; WordPress предлага и управление на съдържание. Често започваме с шаблон, който после променяме. WebSite X5 е предимно настолно средство, затова не го приемаме автоматично за онлайн редактор.')+E('За първа училищна страница визуалното добавяне на заглавие може да е по-лесно. Текстовият редактор дава пряк достъп до кода. Изборът зависи от задачата и уменията.'),[('Текстов редактор','Пишем HTML'),('Визуален редактор','Подреждаме чрез интерфейс'),('Настолен / онлайн','Програма на компютъра / работа през браузър')],C('Кои съчетания са правилни?',['Notepad++ — текстов редактор.','SeaMonkey Composer — визуално средство за страници.','Google Sites — онлайн средство.','Всеки инструмент за уеб дизайн има напълно еднакви функции.','Шаблонът може да бъде начало на визуален проект.','Браузърът и текстовият редактор винаги изпълняват една и съща роля.'],[0,1,2,4],'Инструментите имат различни роли и обхват. Визуалната работа и писането на HTML са различни подходи към описване и подреждане на съдържанието.')),
I('online','Разглеждаме онлайн редактор чрез готов пример',P('В задачите се предлага да се разгледат Google Sites и Wix. Тук използваме готов пример с ученически сайт „Нашият клуб“, без да изискваме регистрация. В работното поле има заглавна част, текст и изображение.','В типичен Google Sites изглед разделът <strong>Вмъкване</strong> предлага елементи за съдържание, <strong>Страници</strong> управлява страниците, а <strong>Теми</strong> променя общия стил. Точният интерфейс може да се изменя, но разграничението между съдържание, страници и оформление остава полезно.','В готовия пример е добавена страница „Дейности“, а в нея — текст и снимка. Прегледът показва как проектът изглежда в различни размери на прозореца. Запазването на чернова и публикуването са различни действия; разглеждането на редактора само по себе си не публикува сайт.')+E('При анализ на училищен или образователен сайт проверяваме дали менюто води към желаната информация и дали страницата остава четима в тесен прозорец. Не заключаваме „статичен“ само защото виждаме текст и снимка.'),[('Вмъкване','Текст, изображение и други елементи'),('Страници','Начало и Дейности'),('Теми / Преглед','Общ стил / проверка на резултата')],C('Кои действия са разграничени правилно?',['Вмъкване добавя съдържание.','Страници управлява страниците в примера.','Преглед помага да проверим изгледа.','Самото отваряне на редактора винаги публикува сайта.','Темата влияе на общото оформление.','Само по цвета на страницата доказваме статичен или динамичен модел.'],[0,1,2,4],'Съдържание, структура, оформление, преглед и публикация са различни действия. Външният вид не доказва вътрешния модел.')),
I('css','CSS: дрехите на съдържанието',P('HTML описва кое е заглавието и кое е абзацът. <strong>CSS</strong> задава как тези елементи да изглеждат — например размер, цвят, разстояния и разположение. Можем да сравним HTML с подреденото съдържание, а CSS с начина, по който го представяме.','В готовия пример заглавието „Нашият клуб“ е синьо и по-едро. Променяме стила му на зелен, без да сменяме самия текст. Ако няколко страници използват общ стил, една промяна може да им даде еднакво ново оформление.','Това разделяне улеснява поддръжката. Не е нужно във всеки абзац да повтаряме едни и същи инструкции за вид. CSS може да задава и движения и ефекти, но те трябва да помагат, а не да пречат на четенето.')+E('Примерно правило: <code>h1 { color: green; }</code> задава зелен цвят за заглавията от този вид. Текстът „Нашият клуб“ остава същият.'),[('HTML','Текстът е заглавие'),('CSS преди','Син цвят'),('CSS след','Зелен цвят; съдържанието е същото')],O('Каква е разликата между HTML и CSS в примера „Нашият клуб“?','Обясни в 3–4 изречения със свои думи и използвай промяната на цвета като пример.','HTML описва съдържанието и показва, че „Нашият клуб“ е заглавие. CSS определя вида му, например размер и цвят. Ако чрез CSS сменим синия цвят със зелен, текстът на заглавието остава същият. Общите стилове помагат страниците да изглеждат последователно. За самопроверка: различи съдържание и представяне; не описвай CSS като програма за купуване на домейн.'))]
build(16,'website-authoring-tools','Специализирани софтуерни средства за създаване на уеб сайтове','46–47',P('Когато натиснеш връзка в училищен сайт, браузърът показва друга страница. Някой предварително е описал и подредил нейното съдържание.','Ще разбереш какво са страница, сайт и хипервръзка, как се различават видовете сайтове и с какви редактори се създават. Ще видиш конкретни примери за HTML и CSS, без да е необходимо да регистрираш профил или да публикуваш сайт.'),topics,['<strong>Страниците са свързани чрез хипервръзки и се показват от браузър.</strong>','<strong>Сайтът е организирано цяло от тематично свързани страници.</strong>','<strong>Статичният модел изпраща подготвени страници; динамичният може да ги съставя според заявката.</strong>','<strong>Редакторите могат да са текстови или визуални, настолни или онлайн.</strong>','<strong>HTML описва съдържанието, CSS — неговото представяне.</strong>'],['Стр.46: WWW/хипертекст/HTML/тагове/браузъри/връзки/страница/сайт/история; класификация по цел с всички пет вида; анализ на училищен сайт.','Стр.47: статичен/динамичен/сървър/данни/шаблон/CMS; всички назовани групи редактори и примери; Google Sites/Wix като готов интерфейсен пример; CSS и навигация, включително приложим анализ на образователен сайт.'],[('MDN: HTML','https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Basic_HTML_syntax'),('MDN: CSS','https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/What_is_CSS'),('CERN: история на Web','https://home.cern/science/computing/the-birth-of-the-web/short-history-web/'),('Google Sites: създаване','https://support.google.com/sites/answer/98081')], 'Поправени абсолютни твърдения: статичен сайт не е непременно по-бърз; видът не се доказва по изглед; блог не изисква форум; първоначални страници1990/публично представяне1991; WebSiteX5 не е общо онлайн редактор. Не се препоръчва инсталиране на неподдържан стар инструмент.')
